class Widget {
  int divisor = 5;
  std::vector<std::function<bool(int)>> filters;
public:
  void addFilter() {
    // DANGER: [=] captures 'this' by value
    filters.emplace_back( [=](int value) { 
      return value % divisor == 0; 
    }); 
  }
};
// If the Widget object is destroyed, the filter becomes invalid.
